import json
import os

DEFAULT_THRESHOLDS = {
    "cpu_percent": 85,
    "memory_percent": 90,
    "disk_percent": 80,
}

ENV_PREFIX = "ALERT_THRESHOLD_"


def _read_config_file(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid config file {path}: {exc}") from exc


def _validate_threshold(name, value):
    if not isinstance(value, (int, float)):
        raise TypeError(
            f"threshold {name} must be numeric, got {type(value).__name__}"
        )
    if not 0 <= value <= 100:
        raise ValueError(f"threshold {name} must be between 0 and 100, got {value}")
    return value


def _apply_env_overrides(thresholds):
    for name in thresholds:
        env_name = ENV_PREFIX + name.upper()
        raw = os.environ.get(env_name)
        if raw is None:
            continue
        try:
            thresholds[name] = float(raw)
        except Exception:
            pass
    return thresholds


def load_thresholds(path):
    file_values = _read_config_file(path)
    thresholds = dict(DEFAULT_THRESHOLDS)

    for name, value in file_values.items():
        if name not in thresholds:
            raise KeyError(f"unknown threshold key: {name}")
        thresholds[name] = _validate_threshold(name, value)

    thresholds = _apply_env_overrides(thresholds)

    for name, value in thresholds.items():
        _validate_threshold(name, value)

    return thresholds


if __name__ == "__main__":
    result = load_thresholds("alert_config.json")
    for key, val in result.items():
        print(f"{key}: {val}")
